import {
  MxCpp,
  MxCADUiPrPoint,
  McDbSpline,
  McGePoint3dArray,
  McGeVector3d,
  McObject,
  McGePoint3d,
} from "mxcad";

export default () => {
  const mxcad = new McObject();
  mxcad.create({
    canvas: "#myCanvas",
    locateFile: (fileName: string) => {
      // CDN loading must use resources from wasm/2d-st, due to GitHub restrictions, wasm/2d resources cannot be used
      // To use wasm/2d, browser same-origin policy must be followed or other means used to bypass it
      return self.location.origin + "/mxcad/wasm/2d-st/" + fileName;
    },
    // Directory location for loading fonts
    fontspath: self.location.origin + "/mxcad/fonts",
    // URL for loading converted drawing files
    fileUrl: self.location.origin + "/mxcad/test.mxweb",
    onOpenFileComplete: () => {
      // Draw a spline
      const sp = new McDbSpline();
      const fitPoints = new McGePoint3dArray([
        new McGePoint3d(0, -20, 0),
        new McGePoint3d(20, 20, 0),
        new McGePoint3d(40, -20, 0),
        new McGePoint3d(60, 20, 0),
        new McGePoint3d(80, -20, 0),
        new McGePoint3d(100, 20, 0),
      ]);
      sp.setFitPoints({
        degree: 3,
        fitTolerance: 0.000001,
        tangentsExist: false,
        startTangent: McGeVector3d.kIdentity,
        endTangent: McGeVector3d.kIdentity,
        fitPoints: fitPoints,
      });
      const mxcad = MxCpp.getCurrentMxCAD();
      mxcad.drawEntity(sp);
      mxcad.zoomAll();
    },
  });

  // Draw spline function
  async function Mx_drawSpline() {
    const getPoint = new MxCADUiPrPoint();
    getPoint.setMessage("\\nSpecify the first point:");
    let prvPoint = await getPoint.go();
    if (!prvPoint) return;

    getPoint.setMessage("\\nSpecify the next point:");
    let fitPoints = new McGePoint3dArray();
    fitPoints.append(prvPoint);

    while (true) {
      getPoint.setBasePt(prvPoint as any);
      if (fitPoints.length() == 1) {
        getPoint.setUseBasePt(true);
      } else {
        getPoint.setUseBasePt(false);
        getPoint.setUserDraw((pt, pw) => {
          let tmpFitPoints = new McGePoint3dArray();
          tmpFitPoints.copy(fitPoints);
          tmpFitPoints.append(pt);
          let tmpSPline = new McDbSpline();
          tmpSPline.setFitPoints({
            degree: 3,
            fitTolerance: 0.000001,
            tangentsExist: false,
            startTangent: McGeVector3d.kIdentity,
            endTangent: McGeVector3d.kIdentity,
            fitPoints: tmpFitPoints,
          });
          pw.drawMcDbEntity(tmpSPline);
        });
      }
      let pt = await getPoint.go();
      if (!pt) break;
      fitPoints.append(pt);
      prvPoint = pt;
    }

    if (fitPoints.length() > 2) {
      let sp = new McDbSpline();
      sp.setFitPoints({
        degree: 3,
        fitTolerance: 0.000001,
        tangentsExist: false,
        startTangent: McGeVector3d.kIdentity,
        endTangent: McGeVector3d.kIdentity,
        fitPoints: fitPoints,
      });
      MxCpp.getCurrentMxCAD().drawEntity(sp);
    }
  }

  return (
    <div style="height: 500px; overflow: hidden;">
      <button
        style="height:30px;border:1px solid #ccc;padding:0px 5px;margin-bottom:10px"
        id="myBtn"
        onClick={() => Mx_drawSpline()}
      >
        绘制样条线
      </button>
      <div style="height: 400px;">
        <canvas id="myCanvas" style="height: 300px"></canvas>
      </div>
    </div>
  );
};
